const cases = [
 {title:'报名截止时间，应该以哪份为准？',description:'原通知与补充说明出现两个日期。先确认适用关系，再决定行动。',type:'时间更新',summary:'时间不同，存在明确的延长说明',copy:'补充说明明确指向原通知；本例仅用于展示核对方式。',decision:'本演示中，补充说明明确延长了同一活动的报名时间。实际使用仍需核对来源与适用对象。',sources:[{name:'校园调研计划 · 报名通知',org:'示例活动办公室（虚构）',date:'2026.10.01',body:'本次校园调研计划面向全体在校本科生。报名截止时间为2026年10月15日18:00。申请人需提交报名表与项目简介。'},{name:'关于延长报名时间的补充说明',org:'示例活动办公室（虚构）',date:'2026.10.08',body:'本说明补充2026年10月1日发布的校园调研计划报名通知。报名截止时间延长至2026年10月20日18:00，报名对象与材料要求保持不变。'}],rows:[{name:'报名截止时间',a:'10月15日 18:00',b:'10月20日 18:00',status:'明确更新',note:'后续说明明确写出“延长”，且指向同一活动。',qa:'报名截止时间为2026年10月15日18:00。',qb:'报名截止时间延长至2026年10月20日18:00。',limit:'本例存在明确更新关系。不能仅凭发布日期较晚推断时间已变更。'},{name:'适用对象',a:'全体在校本科生',b:'报名对象保持不变',status:'未发现差异',neutral:true,note:'补充说明沿用原通知对象。',qa:'本次校园调研计划面向全体在校本科生。',qb:'报名对象与材料要求保持不变。',limit:'未发现差异仅针对当前材料，不能据此判断其他人员是否符合资格。'},{name:'提交材料',a:'报名表、项目简介',b:'材料要求保持不变',status:'沿用原要求',neutral:true,note:'本例未新增提交材料。',qa:'申请人需提交报名表与项目简介。',qb:'报名对象与材料要求保持不变。',limit:'演示结果不涉及真实活动；实际材料清单需回到完整通知核对。'}]},
 {title:'学校与学院的截止时间，真的冲突吗？',description:'相同事项，不同提交环节。日期不同也可能各有适用范围。',type:'适用范围',summary:'两个日期对应不同的提交环节',copy:'学院收集与学校汇总是两件事，本例不能把较晚日期直接当成学生截止时间。',decision:'本演示中，学生向学院提交的时间更早，学院再向学校汇总。应根据自己的角色确认对应环节。',sources:[{name:'示例学校 · 项目申报安排',org:'示例学校项目中心（虚构）',date:'2026.10.02',body:'各学院须于2026年10月22日17:00前提交汇总表及推荐项目。每个推荐项目应包含申请书和指导意见。'},{name:'示例学院 · 材料收集通知',org:'示例学院办公室（虚构）',date:'2026.10.03',body:'本学院学生须于2026年10月18日17:00前提交申请书和指导意见，以便学院审核并于10月22日前完成学校汇总。'}],rows:[{name:'截止时间',a:'10月22日 17:00',b:'10月18日 17:00',status:'环节不同',note:'学校接收学院汇总；学院接收学生材料。',qa:'各学院须于2026年10月22日17:00前提交汇总表及推荐项目。',qb:'本学院学生须于2026年10月18日17:00前提交申请书和指导意见。',limit:'不能选择更晚日期作为统一截止时间。需先明确用户的角色与提交环节。'},{name:'提交对象',a:'各学院 → 学校',b:'学生 → 学院',status:'对象不同',note:'分别适用，不直接构成矛盾。',qa:'各学院须于2026年10月22日17:00前提交汇总表及推荐项目。',qb:'本学院学生须于2026年10月18日17:00前提交申请书和指导意见。',limit:'适用对象与接收方应共同核对，单独比较日期容易误判。'},{name:'项目材料',a:'申请书、指导意见',b:'申请书、指导意见',status:'未发现差异',neutral:true,note:'当前两份材料中的项目要求一致。',qa:'每个推荐项目应包含申请书和指导意见。',qb:'提交申请书和指导意见。',limit:'不代表完整申请要求已覆盖，其他附件仍可能另有规定。'}]},
 {title:'去年的服务时间，今年还能直接用吗？',description:'旧网页与当前说明各有信息，但证据不足以确认现在的开放时间。',type:'时效待确认',summary:'存在时间差异，当前适用性尚不能确认',copy:'已知资料缺少明确生效说明。旧日期本身不能证明信息失效。',decision:'本演示建议补充当前服务安排或联系发布方确认，不依据两份不完整资料生成确定结论。',sources:[{name:'示例阅览室 · 历史开放说明',org:'示例阅览室（虚构）',date:'2025.09.01',body:'本学期阅览室开放时间为每日8:00—22:00。本安排适用于2025年秋季学期。'},{name:'示例阅览室 · 页面摘录',org:'示例阅览室（虚构）',date:'未提供',body:'阅览室开放时间为9:00—21:00。页面摘录未提供发布时间、生效日期或适用学期。'}],rows:[{name:'开放时间',a:'08:00—22:00',b:'09:00—21:00',status:'表述有差异',note:'不能据此判断哪一份适用于当前日期。',qa:'本学期阅览室开放时间为每日8:00—22:00。',qb:'阅览室开放时间为9:00—21:00。',limit:'第二份资料没有发布日期与生效范围。需要补充当前有效公告。'},{name:'适用期间',a:'2025年秋季学期',b:'未提供',status:'信息不足',note:'第一份有明确范围，第二份缺少范围。',qa:'本安排适用于2025年秋季学期。',qb:'页面摘录未提供发布时间、生效日期或适用学期。',limit:'仅凭页面仍能打开，不代表安排仍然有效。'},{name:'发布日期',a:'2025年9月1日',b:'未提供',status:'待核实',note:'无法完整建立版本关系。',qa:'本安排适用于2025年秋季学期。',qb:'页面摘录未提供发布时间、生效日期或适用学期。',limit:'获取时间不等于发布时间；不能替缺失日期补上推测值。'}]}
];
const $ = id => document.getElementById(id);
const escapeHTML = value => String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let currentCase=0, currentRow=0, pasted=[];
let toastTimer;
function toast(message){$('toast').textContent=message;$('toast').classList.remove('hidden');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.add('hidden'),4200);}
function showPage(id){document.querySelectorAll('.page').forEach(p=>p.classList.toggle('hidden',p.id!==id));document.querySelectorAll('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===(id==='workbench'?'home':id)));window.scrollTo({top:0,behavior:'instant'});}
function caseList(){return cases.map((c,i)=>`<button class="case-item" data-case="${i}"><span class="case-index">0${i+1}</span><span><strong>${escapeHTML(c.title)}</strong><p>${escapeHTML(c.description)}</p><span class="case-type">${escapeHTML(c.type)} / 演示资料</span></span><span class="case-arrow" aria-hidden="true">↗</span></button>`).join('');}
$('home-cases').innerHTML=caseList();$('example-cases').innerHTML=caseList();
document.querySelectorAll('[data-case]').forEach(b=>b.addEventListener('click',()=>openCase(Number(b.dataset.case))));
document.querySelectorAll('[data-page]').forEach(b=>b.addEventListener('click',()=>showPage(b.dataset.page)));
document.querySelector('.brand').addEventListener('click',e=>{e.preventDefault();showPage('home');});
function openCase(index){currentCase=index;currentRow=0;const c=cases[index];$('case-title').textContent=c.title;$('case-description').textContent=c.description;$('summary-title').textContent=c.summary;$('summary-copy').textContent=c.copy;$('decision').textContent=c.decision;
 $('sources').innerHTML=c.sources.map((s,i)=>`<article class="source-item"><span class="source-code">SOURCE ${i?'B':'A'} · 虚构材料</span><h3>${escapeHTML(s.name)}</h3><p>${escapeHTML(s.org)}</p><p>发布：${escapeHTML(s.date)}</p></article>`).join('');
 $('comparison').innerHTML=c.rows.map((r,i)=>`<button class="compare-row ${i===0?'selected':''}" data-row="${i}" aria-pressed="${i===0}"><div class="row-heading"><span>${escapeHTML(r.name)}</span><span class="row-status ${r.neutral?'neutral':''}">${escapeHTML(r.status)}</span></div><div class="row-values"><div><small>来源 A</small>${escapeHTML(r.a)}</div><div><small>来源 B</small>${escapeHTML(r.b)}</div></div><div class="row-note">${escapeHTML(r.note)}</div></button>`).join('');
 $('timeline').innerHTML=c.sources.map((s,i)=>`<article class="timeline-item"><time>${escapeHTML(s.date)}</time><h3>${escapeHTML(s.name)}</h3><p>${escapeHTML(i===0?'原始材料':'补充或对照材料')} · ${escapeHTML(s.org)}</p></article>`).join('')+'<p class="timeline-warning">顺序展示不代表优先级。日期缺失时，不能确认版本先后。</p>';
 document.querySelectorAll('[data-row]').forEach(b=>b.addEventListener('click',()=>selectRow(Number(b.dataset.row))));selectRow(0);setView('comparison');showPage('workbench');}
function selectRow(index){currentRow=index;const c=cases[currentCase],r=c.rows[index];document.querySelectorAll('[data-row]').forEach(b=>{b.classList.toggle('selected',Number(b.dataset.row)===index);b.setAttribute('aria-pressed',Number(b.dataset.row)===index);});$('evidence').innerHTML=`<p class="evidence-topic">当前核对项目 / ${String(index+1).padStart(2,'0')}</p><h3>${escapeHTML(r.name)}</h3>${[r.qa,r.qb].map((q,i)=>`<figure class="quote-block"><cite>来源 ${i?'B':'A'} · ${escapeHTML(c.sources[i].name)}</cite><blockquote>“${escapeHTML(q)}”</blockquote><small>演示原文摘录 · 虚构材料</small></figure>`).join('')}<div class="evidence-limit"><span class="micro">还需要留意</span><p>${escapeHTML(r.limit)}</p></div><button class="secondary original-button" id="original-open">查看两份完整演示原文 ↗</button>`;$('original-open').addEventListener('click',showOriginal);}
function setView(view){$('comparison').classList.toggle('hidden',view!=='comparison');$('timeline').classList.toggle('hidden',view!=='timeline');document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('selected',b.dataset.view===view));}
document.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>setView(b.dataset.view)));
$('back').addEventListener('click',()=>showPage('home'));$('change-case').addEventListener('click',()=>showPage('examples'));
$('start').addEventListener('click',()=>{if(pasted.length||$('question').value.trim()){toast('尚未接入真实诊断。现在打开固定示例，与输入内容无关。');}openCase(0);});
$('paste-open').addEventListener('click',()=>{$('paste-dialog').showModal();});$('paste-close').addEventListener('click',()=>$('paste-dialog').close());
$('paste-form').addEventListener('submit',e=>{e.preventDefault();pasted.push({title:$('paste-title').value,body:$('paste-text').value});$('source-count').textContent=`${pasted.length} 份待核对资料`;$('source-preview').innerHTML=`<span class="file-outline" aria-hidden="true">≡</span><span>${escapeHTML(pasted.at(-1).title)}<small>已临时保留 · 真实核对功能尚未接入</small></span>`;$('paste-dialog').close();$('paste-form').reset();toast('资料仅临时保存在当前页面，刷新后清除。');});
const originalDialog=document.createElement('dialog');originalDialog.id='original-dialog';document.body.appendChild(originalDialog);
function showOriginal(){const c=cases[currentCase];originalDialog.innerHTML=`<div class="pane-title">完整演示原文<button aria-label="关闭原文" id="original-close">×</button></div><p>以下内容为虚构材料，未经联网获取。</p>${c.sources.map(s=>`<article><h3>${escapeHTML(s.name)}</h3><p>${escapeHTML(s.org)} / ${escapeHTML(s.date)}</p><p style="color:var(--ink);font-size:15px;line-height:2">${escapeHTML(s.body)}</p></article>`).join('')}`;$('original-close').addEventListener('click',()=>originalDialog.close());originalDialog.showModal();}
function toggleTweaks(open){$('tweaks').classList.toggle('hidden',!open);$('tweaks-toggle').setAttribute('aria-expanded',open);}
$('tweaks-toggle').addEventListener('click',()=>toggleTweaks($('tweaks').classList.contains('hidden')));$('tweaks-close').addEventListener('click',()=>toggleTweaks(false));$('variant').addEventListener('change',e=>{document.body.classList.remove('reading','compact');if(e.target.value!=='standard')document.body.classList.add(e.target.value);});
